/** Isolated synthetic quota failure-injection lane. Actual production cache,
 * reader and parser; generated bytes, synthetic IndexedDB and owned loopback
 * GETs only. No browser, credentials, provider, household or native state. */
import assert from 'node:assert/strict';
import { actorA, derivative, homeA, createProcesses, startSyntheticOwner } from './native-geometry-persistence-harness.mjs';
import { createSyntheticDisk, syntheticRecords } from './synthetic-indexeddb.mjs';

const mesh = await derivative('Synthetic quota export');
const owner = await startSyntheticOwner({ mesh });
try {
  const openProcess = await createProcesses(owner);
  const cold = async (session, expected, order) => {
    const page = await openProcess(session);
    try { assert.deepEqual(await page.open(undefined, order), expected); return page.database; }
    finally { await page.close(); }
  };
  const disk = createSyntheticDisk({ quota: 0 }), session = { disk, actorId: actorA, homeId: homeA };
  const database = await cold(session, { descriptors: 1, meshes: 1 });
  assert(disk.quotaAborts > 0);
  assert.equal(syntheticRecords(disk, database, 'entries').length, 0);
  await cold(session, { descriptors: 1, meshes: 1 });
  console.log('PASS zero storage quota: scan opens from server; next cold open downloads again');

  disk.quota = Infinity;
  await cold(session, { descriptors: 1, meshes: 1 });
  await cold(session, { descriptors: 1, meshes: 0 });
  console.log('PASS quota restored: next open stores bytes and the following cold open downloads none');

  // Three distinct logical floors exceed the origin's two-and-a-half-mesh
  // quota while remaining below the cache's own entry and byte bounds.
  const bounded = createSyntheticDisk({ quota: Math.floor(mesh.bytes.byteLength * 2.5) });
  const other = { version: 1, stores: new Map([['drafts', { keyPath: 'id', records: new Map([
    ['synthetic-unsent', { id: 'synthetic-unsent', data: new Uint8Array([42]).buffer }],
  ]) }]]) };
  bounded.databases.set('synthetic-other-store', other);
  owner.state.floors = 3;
  const boundedSession = { disk: bounded, actorId: actorA, homeId: homeA };
  await cold(boundedSession, { descriptors: 1, meshes: 3 });
  assert(bounded.quotaAborts > 0, 'A real synthetic transaction quota abort must occur');
  assert.equal(syntheticRecords(bounded, database, 'entries').length, 2);
  await cold(boundedSession, { descriptors: 1, meshes: 0 }, [1, 2]);
  assert.deepEqual(new Uint8Array(other.stores.get('drafts').records.get('synthetic-unsent').data), new Uint8Array([42]));
  console.log('PASS quota recovery evicts the oldest cached scan, retains two current floors and preserves the separate synthetic draft store');
} finally { await owner.close(); }
console.log('PASS isolated synthetic scan-cache quota recovery; not browser or iOS proof');
